package com.bananalab.lite;
import org.json.*;import java.util.*;
/** Compiled selection/planning policy, stable host executor and scene validation. */
final class PlannerDispatch{
 static final ThreadLocal<String[]> receipt=new ThreadLocal<>();
 static CreatorSession.Result plan(String input,SceneDraft base,boolean append)throws Exception{if(Boolean.TRUE.equals(CapabilityBench.testing.get()))return null;ProjectRuntime.Snapshot snapshot=ProjectRuntime.active;if(snapshot.planner==null)return null;String q=ChatLanguage.normalize(input);String[] result;try{result=(String[])snapshot.planner.invoke(null,q,PlannerExperience.scores(snapshot.plannerData,q));}catch(Exception e){ProjectRuntime.error="El módulo del planificador falló; usé el planificador base.";return null;}if(result==null)return null;if(result.length!=4)throw new IllegalArgumentException("Salida del planificador inválida.");SceneDraft d=base==null?new SceneDraft():base.copy();SceneDraft.Actor a=ScenePlanner.resolve(d,result[1],true),other=result[2].isEmpty()?null:ScenePlanner.resolve(d,result[2],true);if(a==null||(!result[2].isEmpty()&&(other==null||other==a)))return CreatorSession.say("Nombrá dos personajes existentes o tipos reconocidos para esa receta; conservé la escena.");if(!append){d.actions.clear();d.actors.clear();d.slots.clear();d.targets.clear();d.recipients.clear();d.dialogue.clear();}int slot=0;for(int i=0;i<d.actions.size();i++)slot=Math.max(slot,d.slot(i)+1);JSONArray steps=new JSONArray(result[3]);for(int i=0;i<steps.length();i++){JSONObject step=steps.getJSONObject(i);if(slot>=SceneTiming.MAX_BEATS)return CreatorSession.say("La receta supera los tiempos disponibles; conservé la escena.");String who=step.getString("who"),move=step.getString("move");if(who.equals("ambos")){SceneDirector.step(d,a,move,slot,"","");SceneDirector.step(d,other,move,slot,"","");}else SceneDirector.step(d,who.equals("actor")?a:other,move,slot,"","");slot++;}SceneTiming.fit(d);SceneConsistency.require(d);receipt.set(new String[]{q,result[0],snapshot.plannerData.toString()});return new CreatorSession.Result(true,"Planificador Java · receta "+result[0]+"\n"+SceneAudit.report(d),d);}
}
